ARCHIVE_SUFFIXES = (".zip", ".rar")
# Records of one archive (or of one request) were written within seconds of each other.
GROUP_GAP = timedelta(minutes=2)


def _group_key(record):
    """(kind, name) of the history line a pre-existing record belongs to, or None for a line of its own."""
